import {adaptResume,cleanResume,resumeFields,fingerprint,safeFilename} from './resume.js';
import {mountPortfolio,mountApplicationTools} from './portfolio-ui.js';
import {textChanges} from './portfolio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountResume({getState,getEditingJob,persist,confirmAction,markApplied}){
 const $=s=>document.querySelector(s);let activeId=null,pendingJob=null,baseLoaded=false;
 const button=document.createElement('button');button.id='resume-profile-open';button.type='button';button.className='text-button';button.textContent='Моё резюме';$('#profile-open').after(button);
 const jobButton=document.createElement('button');jobButton.id='prepare-resume';jobButton.type='button';jobButton.className='secondary';jobButton.textContent='Сохранить и подготовить CV';$('#job-dialog .dialog-actions').prepend(jobButton);
 const baseDialog=document.createElement('dialog');baseDialog.id='resume-base-dialog';baseDialog.setAttribute('aria-labelledby','resume-base-title');
 baseDialog.innerHTML=`<form id="resume-base-form"><div class="dialog-top"><h2 id="resume-base-title">Базовое резюме</h2><button type="button" data-resume-close class="small-button">Закрыть</button></div><div class="dialog-body"><p>Только подтверждённые факты. Это твоя личная база для адаптации. В локальном демо используются вымышленные данные. Заполняй её на английском: документы собираются на английском.</p><p id="resume-origin" class="field-help"></p><div class="form-grid">${Object.entries(resumeFields).map(([k,label])=>`<label class="${['fullName','email','phone','location'].includes(k)?'':'wide'}">${label}${['fullName','email','phone','location'].includes(k)?`<input name="${k}" ${k==='fullName'?'required':''} type="${k==='email'?'email':'text'}" maxlength="4000">`:`<textarea name="${k}" rows="${['education','experience','projects'].includes(k)?5:3}" maxlength="${['education','experience','projects'].includes(k)?12000:4000}"></textarea>`}</label>`).join('')}</div><p id="resume-base-error" class="form-error" role="alert"></p></div><div class="dialog-actions"><button type="submit" class="primary">Сохранить базовое CV</button></div></form>`;
 document.body.append(baseDialog);
 const draftDialog=document.createElement('dialog');draftDialog.id='resume-draft-dialog';draftDialog.setAttribute('aria-labelledby','resume-draft-title');
 draftDialog.innerHTML=`<div class="dialog-top"><div><span class="eyebrow">ПОДГОТОВКА ОТКЛИКА</span><h2 id="resume-draft-title">Резюме под вакансию</h2></div><button type="button" data-resume-close class="small-button">Закрыть</button></div><div class="dialog-body"><p id="resume-target"></p><div class="context-box"><strong>Проверь перед отправкой</strong>Навыки и проекты упорядочены по совпадениям с требованиями карточки. Генератор использует только базовое CV, не читает ссылку работодателя и не добавляет новые достижения. Полные требования можно вставить в карточку вакансии.</div><p id="resume-draft-meta" class="field-help"></p><p id="resume-evidence"></p><p id="resume-stale" class="strategy-warning" hidden>Базовое CV или вакансия изменились. Сохранённый текст оставлен как есть; при необходимости пересобери черновик.</p><div class="resume-tools"><button id="resume-edit-base" class="small-button">Изменить базу</button><button id="resume-regenerate" class="small-button">Пересобрать черновик</button></div><label class="resume-block">Резюме — можно отредактировать<textarea id="resume-cv-text" rows="20" maxlength="30000"></textarea></label><label class="resume-block">Тема письма<input id="resume-subject" maxlength="500"></label><label class="resume-block">Сопроводительное письмо<textarea id="resume-cover-text" rows="12" maxlength="12000"></textarea></label><label class="favorite-field"><input id="resume-reviewed" type="checkbox"> Я проверил факты, контакты и текст</label><p id="resume-result" role="status"></p><div class="resume-tools"><button id="resume-download-cv" class="primary">Скачать CV · PDF</button><button id="resume-download-cover" class="secondary">Письмо · PDF</button><button id="resume-download-text" class="small-button">Оба текста · TXT</button></div><p class="field-help">Отправка пока вручную: скачай PDF и приложи его к отклику. Почта не подключена. Скачивание не означает отправку.</p><p><a id="resume-vacancy-link" target="_blank" rel="noopener noreferrer">Открыть вакансию для отклика</a></p><button id="resume-mark-applied" class="secondary">Я отправил этот вариант — записать отклик</button><p class="field-help">Нажимай только после фактической отправки. Версия CV и письмо сохранятся в карточке.</p></div><div class="dialog-actions"><button id="resume-save-draft" class="primary">Сохранить черновик</button></div>`;
 document.body.append(draftDialog);
 const currentJob=()=>getState().jobs.find(j=>j.id===activeId);
 let dirty=false,workingDraft=null;
 const portfolio=mountPortfolio({getState,persist,onChange:()=>{if(draftDialog.open)$('#resume-stale').hidden=false}});
 const effectiveBase=()=>portfolio.base();
 function generate(j,selected){const base=effectiveBase(),choices=portfolio.choices(j);const projects=selected??j.resumeProjectSelection??choices.slice(0,2).map(p=>p.text);const valid=projects.filter(p=>choices.some(c=>c.text===p));const d=adaptResume({...base,projects:valid.join('\n\n')},j);d.fingerprint=fingerprint(base,j);d.selectedProjects=valid;d.changes=textChanges(j.applicationDraft?.cvText||adaptResume(getState().resumeProfile,j).cvText,d.cvText);return d}
 function rebuild(selected){confirmAction('Пересобрать черновик?','Текущие правки будут заменены подтверждёнными фактами и выбранными проектами. Отправленная версия останется в истории.',()=>{try{const j=currentJob(),d=generate(j,selected);if(selected){j.resumeProjectSelection=selected;persist()}populate({...d,version:j.applicationDraft?.version||''},j);dirty=true}catch(e){$('#resume-result').textContent=e.message}},'Пересобрать')}
 const applicationTools=mountApplicationTools({base:effectiveBase,currentJob,currentDraft:()=>workingDraft,regenerate:rebuild,persist,getState,saveDraft:save});
 function closeDraft(){if(!dirty){draftDialog.close();return}confirmAction('Закрыть без сохранения?','Правки черновика после последнего сохранения будут потеряны.',()=>{dirty=false;draftDialog.close()},'Закрыть без сохранения')}
 draftDialog.querySelector('[data-resume-close]').onclick=closeDraft;draftDialog.addEventListener('cancel',e=>{e.preventDefault();closeDraft()});
 baseDialog.querySelector('[data-resume-close]').onclick=()=>{pendingJob=null;baseDialog.close()};
 async function openBase(job=null){
  pendingJob=job;$('#resume-base-error').textContent='';$('#resume-origin').textContent='';
  if(!getState().resumeProfile&&!baseLoaded){
   try{const r=await fetch('/api/resume-baseline',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();if(d.resume){getState().resumeProfile=cleanResume(d.resume);getState().resumeSourceNote=d.resume.sourceNote;persist();}baseLoaded=true}catch{$('#resume-base-error').textContent='Не удалось загрузить исходное CV. Можно заполнить поля вручную или повторить позже.'}
  }
  const p=cleanResume(getState().resumeProfile);for(const k of Object.keys(resumeFields))$('#resume-base-form').elements[k].value=p[k];
  $('#resume-origin').textContent=getState().resumeSourceNote?'База подготовлена по загруженному CV. Дата рождения, пол и фото не включены. Проверь контакты и при необходимости обнови факты.':'Заполни собственное CV. Навыки из плана обучения не добавляются автоматически.';
  baseDialog.showModal();
 }
 button.onclick=()=>openBase();
 $('#resume-base-form').onsubmit=e=>{e.preventDefault();const base=cleanResume(Object.fromEntries(new FormData(e.currentTarget)));if(!base.fullName||(!base.education&&!base.experience&&!base.projects)){$('#resume-base-error').textContent='Нужны имя и хотя бы образование, опыт или проект.';return}getState().resumeProfile=base;persist('Базовое резюме сохранено');baseDialog.close();const job=pendingJob;pendingJob=null;if(job)openDraft(job);else if(draftDialog.open)$('#resume-stale').hidden=false;};
 function populate(d,j){workingDraft=structuredClone(d);dirty=false;$('#resume-target').textContent=`${j.title} · ${j.company}`;$('#resume-cv-text').value=d.cvText;$('#resume-cover-text').value=d.coverText;$('#resume-subject').value=d.subject;$('#resume-reviewed').checked=d.reviewed===true;$('#resume-result').textContent='';$('#resume-draft-meta').textContent=d.version?`Сохранённая версия: ${d.version}`:'Новый черновик · ещё не сохранён';$('#resume-evidence').textContent=`Выделены навыки: ${d.matched?.join(', ')||'нет явных совпадений'}. Требования без подтверждения в CV: ${d.missing?.join(', ')||'не выявлены в распознанном стеке'}.`;$('#resume-stale').hidden=d.fingerprint===fingerprint(effectiveBase(),j);const link=$('#resume-vacancy-link');try{const u=new URL(j.url);if(!['http:','https:'].includes(u.protocol))throw Error();link.href=u.href;link.hidden=false}catch{link.removeAttribute('href');link.hidden=true}$('#resume-mark-applied').disabled=!!j.appliedAt;$('#resume-mark-applied').textContent=j.appliedAt?'Отклик уже записан':'Я отправил этот вариант — записать отклик';applicationTools.render(j,d);}
 function openDraft(j){activeId=j.id;try{populate(j.applicationDraft||generate(j),j);draftDialog.showModal()}catch{openBase(j)}}
 jobButton.onclick=()=>{$('#job-form').requestSubmit();if($('#job-dialog').open)return;const j=getEditingJob();if(!j)return;if(!getState().resumeProfile)return openBase(j);openDraft(j)};
 for(const id of ['resume-cv-text','resume-cover-text','resume-subject'])$('#'+id).addEventListener('input',()=>{dirty=true;$('#resume-reviewed').checked=false});
 $('#resume-reviewed').onchange=()=>{dirty=true};
 function save(){const j=currentJob();if(!j){$('#resume-result').textContent='Карточка больше недоступна.';return false}const cvText=$('#resume-cv-text').value.trim(),coverText=$('#resume-cover-text').value.trim();if(!cvText){$('#resume-result').textContent='Резюме не может быть пустым.';return false}const changed=dirty||!j.applicationDraft;const previous=j.applicationDraft;const version=changed?`CV-${new Date().toISOString().slice(0,10)}-${(previous?.revision||0)+1}`:previous.version;
  j.applicationDraft={...workingDraft,cvText,coverText,subject:$('#resume-subject').value.trim(),reviewed:$('#resume-reviewed').checked,version,revision:changed?(previous?.revision||0)+1:previous.revision,savedAt:new Date().toISOString()};workingDraft=structuredClone(j.applicationDraft);dirty=false;persist('Черновик отклика сохранён');$('#resume-draft-meta').textContent=`Сохранённая версия: ${version}`;$('#resume-result').textContent='Черновик сохранён в карточке. Отправка не выполнялась.';return true;
 }
 $('#resume-save-draft').onclick=save;
 $('#resume-edit-base').onclick=()=>openBase();
 $('#resume-regenerate').onclick=()=>rebuild();
 const download=(bytes,type,name)=>{const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 async function pdf(which){if(!$('#resume-reviewed').checked){$('#resume-result').textContent='Сначала проверь текст и поставь отметку подтверждения.';return}if(!save())return;const b=$('#resume-download-'+which);b.disabled=true;try{const {createResumePDF}=await import('./vendor/cv-pdf.js');const r=await fetch('/fonts/DejaVuSans.ttf');if(!r.ok)throw Error('Шрифт не загрузился. Повтори скачивание.');const data=await createResumePDF(which==='cv'?$('#resume-cv-text').value:$('#resume-cover-text').value,new Uint8Array(await r.arrayBuffer()));const j=currentJob();download(data,'application/pdf',`${safeFilename(getState().resumeProfile.fullName)}_${safeFilename(j.company)}_${which}_${safeFilename(j.applicationDraft.version)}.pdf`);$('#resume-result').textContent='PDF подготовлен. Приложи его при отправке отклика.'}catch(e){$('#resume-result').textContent=e.message||'Не удалось создать PDF. Черновик сохранён.'}finally{b.disabled=false}}
 $('#resume-download-cv').onclick=()=>pdf('cv');$('#resume-download-cover').onclick=()=>pdf('cover');
 $('#resume-download-text').onclick=()=>{if(save())download($('#resume-cv-text').value+'\n\n--- COVER LETTER ---\n\n'+$('#resume-subject').value+'\n\n'+$('#resume-cover-text').value,'text/plain;charset=utf-8',safeFilename(currentJob().company)+'_application.txt')};
 $('#resume-mark-applied').onclick=()=>{if(!$('#resume-reviewed').checked){$('#resume-result').textContent='Подтверди проверку отправленного текста.';return}if(!save())return;const j=currentJob();if(j.appliedAt)return;confirmAction('Записать уже отправленный отклик?',`Подтверди, что ты действительно отправил документы в ${j.company}. Эта кнопка сама ничего не отправляет.`,()=>{const live=currentJob();if(!live||live.appliedAt)return;live.sentApplication=structuredClone(live.applicationDraft);live.cvVersion=live.applicationDraft.version;live.coverLetter=live.applicationDraft.coverText;markApplied(live);$('#resume-mark-applied').disabled=true;$('#resume-mark-applied').textContent='Отклик уже записан';$('#resume-result').textContent='Отправленный вариант сохранён, карточка перенесена в отклики.'},'Да, я отправил')};
 return{isOpen:()=>baseDialog.open||draftDialog.open||portfolio.isOpen()};
}
